// Build-time generator for the bundled North American city list.
//
// Reads the offline `country-state-city` dataset (a devDependency, never shipped)
// and emits `src/geo/na-cities.ts`: a flat, sorted, de-duplicated array of
// "City, Region, Country" labels for the US and Canada. The app bundles only
// this generated file, not the full worldwide dataset.
//
// Re-run after bumping `country-state-city`:  node scripts/generate-na-cities.mjs
import { City } from "country-state-city";
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const COUNTRY_LABEL = { US: "USA", CA: "Canada" };

const labels = new Set();
for (const code of Object.keys(COUNTRY_LABEL)) {
  for (const c of City.getCitiesOfCountry(code) ?? []) {
    const name = c.name?.trim();
    if (!name) continue;
    const region = c.stateCode?.trim();
    const country = COUNTRY_LABEL[code];
    labels.add(region ? `${name}, ${region}, ${country}` : `${name}, ${country}`);
  }
}

const sorted = Array.from(labels).sort((a, b) => a.localeCompare(b));

const here = dirname(fileURLToPath(import.meta.url));
const outPath = join(here, "..", "src", "geo", "na-cities.ts");
const body = sorted.map((l) => `  ${JSON.stringify(l)},`).join("\n");
const file = `// GENERATED by scripts/generate-na-cities.mjs. Do not edit by hand.
// US + Canada cities as "City, Region, Country" labels (offline autocomplete source).
// ${sorted.length} entries.
export const NA_CITIES: readonly string[] = [
${body}
];
`;

writeFileSync(outPath, file);
console.log(`Wrote ${sorted.length} cities to ${outPath}`);
